// Restore sprite symbols that have no source file in assets/Material_Icons/.
//
// The sprite is GENERATED by assets/generate_icon_sprite.py from that folder, so
// any symbol present only in the sprite is a hand-added symbol that the next
// generator run would silently delete. This writes each one back as a proper
// source .svg, using the path data ALREADY IN THE SPRITE — which is the same data
// committed to git — reformatted into the house source style.
//
// Run with --write to apply. Default is a report only.

import { readFileSync, writeFileSync, readdirSync } from 'fs';

const SPRITE = 'NUI/assets/material-icons-sprite.svg';
const SRC = 'assets/Material_Icons';

const svg = readFileSync(SPRITE, 'utf8');
const have = new Set(
	readdirSync(SRC).filter(f => f.endsWith('.svg')).map(f => f.slice(0, -4))
);

const symbols = [...svg.matchAll(/<symbol id="([^"]+)" viewBox="([^"]+)">([\s\S]*?)<\/symbol>/g)];

const recovered = [];
for (const [, id, viewBox, inner] of symbols) {
	if (have.has(id)) continue;

	// Keep the geometry verbatim; strip the ns0 namespace noise the sprite carries.
	// Do NOT touch the path data — it is the committed source of truth here.
	const shapes = inner
		.trim()
		.replace(/\s*xmlns:ns0="[^"]*"/g, '')
		.split('\n')
		.map(l => l.trim())
		.filter(Boolean);

	if (!shapes.length) {
		console.log(`  SKIP ${id}: symbol has no drawable shapes`);
		continue;
	}

	// House style: 24px square, black fill, an explicit transparent background
	// path (the generator filters fill="none" elements out), then the geometry.
	const body = [
		`<svg xmlns="http://www.w3.org/2000/svg" height="24px" viewBox="${viewBox}" width="24px" fill="#000000">`,
		`<path d="M0 0h24v24H0z" fill="none"/>`,
		...shapes.map(s => s.replace(/\sfill="[^"]*"/g, '')),
		`</svg>`
	].join('');

	recovered.push({ id, content: body + '\n' });
}

console.log(`${recovered.length} symbol(s) recovered from the sprite:\n`);
for (const r of recovered) console.log(`  ${r.id}`);

if (process.argv.includes('--write')) {
	for (const r of recovered) {
		writeFileSync(`${SRC}/${r.id}.svg`, r.content, 'utf8');
		console.log(`wrote ${SRC}/${r.id}.svg`);
	}
}
